{"implementation": "def solve(case):
    import copy

    # --- field validation ---
    if not isinstance(case, dict) or "payload" not in case:
        raise ValueError("case must have a 'payload' key")
    payload = case["payload"]
    for key in ("segments", "budget"):
        if key not in payload:
            raise ValueError(f"payload missing required key: {key}")
    budget = payload["budget"]
    if not isinstance(budget, int) or isinstance(budget, bool):
        raise ValueError("budget must be an integer")
    segments = payload["segments"]
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")
    for i, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"segment {i} missing field '{field}'")
        if not isinstance(seg["name"], str):
            raise ValueError(f"segment {i} name must be a string")
        for field in ("importance", "minimum", "capacity"):
            if not isinstance(seg[field], (int, float)) or isinstance(seg[field], bool):
                raise ValueError(f"segment {i} field '{field}' must be numeric")
        if seg["minimum"] < 0:
            raise ValueError(f"segment {i} minimum must be non-negative")
        if seg["capacity"] < seg["minimum"]:
            raise ValueError(f"segment {i} capacity must be >= minimum")
        if seg["importance"] < 0:
            raise ValueError(f"segment {i} importance must be non-negative")

    # --- feasibility check ---
    total_min = sum(seg["minimum"] for seg in segments)
    total_cap = sum(seg["capacity"] for seg in segments)
    if budget < total_min:
        raise ValueError(
            f"budget {budget} is below the minimum quota sum {total_min}"
        )
    if budget > total_cap:
        raise ValueError(
            f"budget {budget} exceeds total capacity {total_cap}"
        )

    # --- initialise at minimum quota (no mutation of input) ---
    alloc = [int(seg["minimum"]) for seg in segments]
    remaining = budget - total_min

    # --- greedy token-by-token allocation ---
    # priority score for adding one more token to segment i:
    #   importance / (current_alloc + 1)
    # tie-break: lower original index wins (stable by construction of loop)
    while remaining > 0:
        best_idx = -1
        best_score = None
        for i, seg in enumerate(segments):
            if alloc[i] >= seg["capacity"]:
                continue
            score = seg["importance"] / (alloc[i] + 1)
            if best_score is None or score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            raise ValueError(
                "No segment can absorb remaining budget; infeasible case."
            )
        alloc[best_idx] += 1
        remaining -= 1

    # --- build output (compute aggregate from primitive decisions) ---
    allocations = {seg["name"]: alloc[i] for i, seg in enumerate(segments)}
    name_mapping = {str(i): seg["name"] for i, seg in enumerate(segments)}
    exact_total = sum(alloc)

    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": exact_total
    }
"}
